// ServerInterface represents all server handlers.
type ServerInterface interface {
	// PostAuthCode Text a login code to a +86 number (spec §2.12, 阿里云号码认证 · 短信认证)
	// (POST /auth/code)
	PostAuthCode(w http.ResponseWriter, r *http.Request, params PostAuthCodeParams)
	// PostAuthLogin Log in (signing up on first use) with the texted code
	// (POST /auth/login)
	PostAuthLogin(w http.ResponseWriter, r *http.Request, params PostAuthLoginParams)
	// PostAuthLogout End this token's session; the app keeps its local data (spec §2.12)
	// (POST /auth/logout)
	PostAuthLogout(w http.ResponseWriter, r *http.Request, params PostAuthLogoutParams)
	// GetAvatar A 头像, to any logged-in caller
	// (GET /avatars/{avatar})
	GetAvatar(w http.ResponseWriter, r *http.Request, avatar string, params GetAvatarParams)
	// GetOsmExtract The script and tag rules the 徒步线路 were extracted from OSM with (ODbL, spec §3.3)
	// (GET /data/osm-extract)
	GetOsmExtract(w http.ResponseWriter, r *http.Request)
	// GetHealth Liveness plus database/PostGIS reachability
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request, params GetHealthParams)
	// DeleteMe 注销账号 (spec §2.12)
	// (DELETE /me)
	DeleteMe(w http.ResponseWriter, r *http.Request, params DeleteMeParams)
	// GetMe The logged-in account
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request, params GetMeParams)
	// DeleteMeAvatar 不用头像
	// (DELETE /me/avatar)
	DeleteMeAvatar(w http.ResponseWriter, r *http.Request, params DeleteMeAvatarParams)
	// PutMeAvatar 换头像 (spec ux-v3 §8.4 第 6、8 条)
	// (PUT /me/avatar)
	PutMeAvatar(w http.ResponseWriter, r *http.Request, params PutMeAvatarParams)
	// PutMeNickname 改昵称 (spec ux-v3 §8.4 第 5、8 条)
	// (PUT /me/nickname)
	PutMeNickname(w http.ResponseWriter, r *http.Request, params PutMeNicknameParams)
	// GetNearbyTracks 经过这里的轨迹 (spec §2.8)：the 公开轨迹 passing within radius metres of a point
	// (GET /nearby-tracks)
	GetNearbyTracks(w http.ResponseWriter, r *http.Request, params GetNearbyTracksParams)
	// PostOfflinePackages Clip an offline package (spec §2.3) for a viewport or along a track
	// (POST /offline/packages)
	PostOfflinePackages(w http.ResponseWriter, r *http.Request, params PostOfflinePackagesParams)
	// GetOfflineVersion Version of the offline map data; packages downloaded under another version show "可更新"
	// (GET /offline/version)
	GetOfflineVersion(w http.ResponseWriter, r *http.Request, params GetOfflineVersionParams)
	// GetSearch 搜索 (spec §2.10) online, for places the offline index doesn't have
	// (GET /search)
	GetSearch(w http.ResponseWriter, r *http.Request, params GetSearchParams)
	// GetSync Pull the caller's synced tracks, 标注组 and 标注 changed after a cursor (spec §2.12)
	// (GET /sync)
	GetSync(w http.ResponseWriter, r *http.Request, params GetSyncParams)
	// PostSync Push changes to the caller's tracks, 标注组 and 标注, all or nothing
	// (POST /sync)
	PostSync(w http.ResponseWriter, r *http.Request, params PostSyncParams)
	// PostSyncPhoto Upload a 标注 photo, to set as its photo afterwards
	// (POST /sync/photos)
	PostSyncPhoto(w http.ResponseWriter, r *http.Request, params PostSyncPhotoParams)
	// GetSyncPhoto One of the caller's synced photos
	// (GET /sync/photos/{photo})
	GetSyncPhoto(w http.ResponseWriter, r *http.Request, photo string, params GetSyncPhotoParams)
	// PostTeam Create a 队伍 (spec §2.11); the caller is its 发起人 and gets a 4-digit code to hand out
	// (POST /teams)
	PostTeam(w http.ResponseWriter, r *http.Request, params PostTeamParams)
	// GetTeamCard The active team with this code, to look at before joining; changes nothing
	// (GET /teams/join)
	GetTeamCard(w http.ResponseWriter, r *http.Request, params GetTeamCardParams)
	// PostTeamJoin Join the active team with this code (any other active team is left first)
	// (POST /teams/join)
	PostTeamJoin(w http.ResponseWriter, r *http.Request, params PostTeamJoinParams)
	// GetTeam The team, with the positions stored after `after`
	// (GET /teams/{id})
	GetTeam(w http.ResponseWriter, r *http.Request, id TeamId, params GetTeamParams)
	// PostTeamEnd 结束行程 (发起人 only); everyone stops sharing, the team stays for its 队伍对话
	// (POST /teams/{id}/end)
	PostTeamEnd(w http.ResponseWriter, r *http.Request, id TeamId, params PostTeamEndParams)
	// PostTeamImage Upload a photo for an image message
	// (POST /teams/{id}/images)
	PostTeamImage(w http.ResponseWriter, r *http.Request, id TeamId, params PostTeamImageParams)
	// GetTeamImage A team photo, or its thumbnail (the thumbnail too once the original is gone)
	// (GET /teams/{id}/images/{image})
	GetTeamImage(w http.ResponseWriter, r *http.Request, id TeamId, image string, params GetTeamImageParams)
	// PostTeamLeave 退出队伍; the caller's 尾迹 goes with them. The last one out ends the trip.
	// (POST /teams/{id}/leave)
	PostTeamLeave(w http.ResponseWriter, r *http.Request, id TeamId, params PostTeamLeaveParams)
	// GetTeamLive WebSocket of the team's changes (spec §3.2, in-memory broadcast on the one server)
	// (GET /teams/{id}/live)
	GetTeamLive(w http.ResponseWriter, r *http.Request, id TeamId, params GetTeamLiveParams)
	// PostTeamMessage Send to the 队伍对话 (spec §2.11); goes out to the team's sockets like any change
	// (POST /teams/{id}/messages)
	PostTeamMessage(w http.ResponseWriter, r *http.Request, id TeamId, params PostTeamMessageParams)
	// PostTeamPositions Report the caller's positions to the team
	// (POST /teams/{id}/positions)
	PostTeamPositions(w http.ResponseWriter, r *http.Request, id TeamId, params PostTeamPositionsParams)
	// PutTeamSharing 停止共享 (false) or share again (true); the caller stays in the team either way
	// (PUT /teams/{id}/sharing)
	PutTeamSharing(w http.ResponseWriter, r *http.Request, id TeamId, params PutTeamSharingParams)
	// DeleteTeamTrack 取消 the 队伍轨迹 (发起人 only); members keep theirs
	// (DELETE /teams/{id}/track)
	DeleteTeamTrack(w http.ResponseWriter, r *http.Request, id TeamId, params DeleteTeamTrackParams)
	// GetTeamTrack The 队伍轨迹 with its points (spec §2.11)
	// (GET /teams/{id}/track)
	GetTeamTrack(w http.ResponseWriter, r *http.Request, id TeamId, params GetTeamTrackParams)
	// PutTeamTrack 指定, 更换 or 改起算点 of the 队伍轨迹 (发起人 only)
	// (PUT /teams/{id}/track)
	PutTeamTrack(w http.ResponseWriter, r *http.Request, id TeamId, params PutTeamTrackParams)
	// GetPublicTracksTile 公开轨迹 (spec §2.8, ADR 0002) as a Mapbox Vector Tile, from z 11
	// (GET /tiles/public-tracks/{z}/{x}/{y})
	GetPublicTracksTile(w http.ResponseWriter, r *http.Request, z int, x int, y int, params GetPublicTracksTileParams)
	// GetTerrainTile A tile of the China PMTiles the offline packages are clipped from (spec §3.1), for 地形 online
	// (GET /tiles/terrain/{layer}/{z}/{x}/{y})
	GetTerrainTile(w http.ResponseWriter, r *http.Request, layer GetTerrainTileParamsLayer, z int, x int, y int, params GetTerrainTileParams)
	// GetTiandituTile A 天地图 tile through the server, so the key never ships in the app (spec §2.2)
	// (GET /tiles/tianditu/{layer}/{z}/{x}/{y})
	GetTiandituTile(w http.ResponseWriter, r *http.Request, layer GetTiandituTileParamsLayer, z int, x int, y int, params GetTiandituTileParams)
	// GetVersion API version and the oldest client versionCode still served
	// (GET /version)
	GetVersion(w http.ResponseWriter, r *http.Request, params GetVersionParams)
	// PostWeather 沿途天气 (spec §2.9) for points along a track at their expected arrival times
	// (POST /weather)
	PostWeather(w http.ResponseWriter, r *http.Request, params PostWeatherParams)
}

