// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// PostAuthCode Text a login code to a +86 number (spec §2.12, 阿里云号码认证 · 短信认证)
	// (POST /auth/code)
	PostAuthCode(ctx context.Context, request PostAuthCodeRequestObject) (PostAuthCodeResponseObject, error)
	// PostAuthLogin Log in (signing up on first use) with the texted code
	// (POST /auth/login)
	PostAuthLogin(ctx context.Context, request PostAuthLoginRequestObject) (PostAuthLoginResponseObject, error)
	// PostAuthLogout End this token's session; the app keeps its local data (spec §2.12)
	// (POST /auth/logout)
	PostAuthLogout(ctx context.Context, request PostAuthLogoutRequestObject) (PostAuthLogoutResponseObject, error)
	// GetAvatar A 头像, to any logged-in caller
	// (GET /avatars/{avatar})
	GetAvatar(ctx context.Context, request GetAvatarRequestObject) (GetAvatarResponseObject, error)
	// GetOsmExtract The script and tag rules the 徒步线路 were extracted from OSM with (ODbL, spec §3.3)
	// (GET /data/osm-extract)
	GetOsmExtract(ctx context.Context, request GetOsmExtractRequestObject) (GetOsmExtractResponseObject, error)
	// GetHealth Liveness plus database/PostGIS reachability
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// DeleteMe 注销账号 (spec §2.12)
	// (DELETE /me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// GetMe The logged-in account
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// DeleteMeAvatar 不用头像
	// (DELETE /me/avatar)
	DeleteMeAvatar(ctx context.Context, request DeleteMeAvatarRequestObject) (DeleteMeAvatarResponseObject, error)
	// PutMeAvatar 换头像 (spec ux-v3 §8.4 第 6、8 条)
	// (PUT /me/avatar)
	PutMeAvatar(ctx context.Context, request PutMeAvatarRequestObject) (PutMeAvatarResponseObject, error)
	// PutMeNickname 改昵称 (spec ux-v3 §8.4 第 5、8 条)
	// (PUT /me/nickname)
	PutMeNickname(ctx context.Context, request PutMeNicknameRequestObject) (PutMeNicknameResponseObject, error)
	// GetNearbyTracks 经过这里的轨迹 (spec §2.8)：the 公开轨迹 passing within radius metres of a point
	// (GET /nearby-tracks)
	GetNearbyTracks(ctx context.Context, request GetNearbyTracksRequestObject) (GetNearbyTracksResponseObject, error)
	// PostOfflinePackages Clip an offline package (spec §2.3) for a viewport or along a track
	// (POST /offline/packages)
	PostOfflinePackages(ctx context.Context, request PostOfflinePackagesRequestObject) (PostOfflinePackagesResponseObject, error)
	// GetOfflineVersion Version of the offline map data; packages downloaded under another version show "可更新"
	// (GET /offline/version)
	GetOfflineVersion(ctx context.Context, request GetOfflineVersionRequestObject) (GetOfflineVersionResponseObject, error)
	// GetSearch 搜索 (spec §2.10) online, for places the offline index doesn't have
	// (GET /search)
	GetSearch(ctx context.Context, request GetSearchRequestObject) (GetSearchResponseObject, error)
	// GetSync Pull the caller's synced tracks, 标注组 and 标注 changed after a cursor (spec §2.12)
	// (GET /sync)
	GetSync(ctx context.Context, request GetSyncRequestObject) (GetSyncResponseObject, error)
	// PostSync Push changes to the caller's tracks, 标注组 and 标注, all or nothing
	// (POST /sync)
	PostSync(ctx context.Context, request PostSyncRequestObject) (PostSyncResponseObject, error)
	// PostSyncPhoto Upload a 标注 photo, to set as its photo afterwards
	// (POST /sync/photos)
	PostSyncPhoto(ctx context.Context, request PostSyncPhotoRequestObject) (PostSyncPhotoResponseObject, error)
	// GetSyncPhoto One of the caller's synced photos
	// (GET /sync/photos/{photo})
	GetSyncPhoto(ctx context.Context, request GetSyncPhotoRequestObject) (GetSyncPhotoResponseObject, error)
	// PostTeam Create a 队伍 (spec §2.11); the caller is its 发起人 and gets a 4-digit code to hand out
	// (POST /teams)
	PostTeam(ctx context.Context, request PostTeamRequestObject) (PostTeamResponseObject, error)
	// GetTeamCard The active team with this code, to look at before joining; changes nothing
	// (GET /teams/join)
	GetTeamCard(ctx context.Context, request GetTeamCardRequestObject) (GetTeamCardResponseObject, error)
	// PostTeamJoin Join the active team with this code (any other active team is left first)
	// (POST /teams/join)
	PostTeamJoin(ctx context.Context, request PostTeamJoinRequestObject) (PostTeamJoinResponseObject, error)
	// GetTeam The team, with the positions stored after `after`
	// (GET /teams/{id})
	GetTeam(ctx context.Context, request GetTeamRequestObject) (GetTeamResponseObject, error)
	// PostTeamEnd 结束行程 (发起人 only); everyone stops sharing, the team stays for its 队伍对话
	// (POST /teams/{id}/end)
	PostTeamEnd(ctx context.Context, request PostTeamEndRequestObject) (PostTeamEndResponseObject, error)
	// PostTeamImage Upload a photo for an image message
	// (POST /teams/{id}/images)
	PostTeamImage(ctx context.Context, request PostTeamImageRequestObject) (PostTeamImageResponseObject, error)
	// GetTeamImage A team photo, or its thumbnail (the thumbnail too once the original is gone)
	// (GET /teams/{id}/images/{image})
	GetTeamImage(ctx context.Context, request GetTeamImageRequestObject) (GetTeamImageResponseObject, error)
	// PostTeamLeave 退出队伍; the caller's 尾迹 goes with them. The last one out ends the trip.
	// (POST /teams/{id}/leave)
	PostTeamLeave(ctx context.Context, request PostTeamLeaveRequestObject) (PostTeamLeaveResponseObject, error)
	// GetTeamLive WebSocket of the team's changes (spec §3.2, in-memory broadcast on the one server)
	// (GET /teams/{id}/live)
	GetTeamLive(ctx context.Context, request GetTeamLiveRequestObject) (GetTeamLiveResponseObject, error)
	// PostTeamMessage Send to the 队伍对话 (spec §2.11); goes out to the team's sockets like any change
	// (POST /teams/{id}/messages)
	PostTeamMessage(ctx context.Context, request PostTeamMessageRequestObject) (PostTeamMessageResponseObject, error)
	// PostTeamPositions Report the caller's positions to the team
	// (POST /teams/{id}/positions)
	PostTeamPositions(ctx context.Context, request PostTeamPositionsRequestObject) (PostTeamPositionsResponseObject, error)
	// PutTeamSharing 停止共享 (false) or share again (true); the caller stays in the team either way
	// (PUT /teams/{id}/sharing)
	PutTeamSharing(ctx context.Context, request PutTeamSharingRequestObject) (PutTeamSharingResponseObject, error)
	// DeleteTeamTrack 取消 the 队伍轨迹 (发起人 only); members keep theirs
	// (DELETE /teams/{id}/track)
	DeleteTeamTrack(ctx context.Context, request DeleteTeamTrackRequestObject) (DeleteTeamTrackResponseObject, error)
	// GetTeamTrack The 队伍轨迹 with its points (spec §2.11)
	// (GET /teams/{id}/track)
	GetTeamTrack(ctx context.Context, request GetTeamTrackRequestObject) (GetTeamTrackResponseObject, error)
	// PutTeamTrack 指定, 更换 or 改起算点 of the 队伍轨迹 (发起人 only)
	// (PUT /teams/{id}/track)
	PutTeamTrack(ctx context.Context, request PutTeamTrackRequestObject) (PutTeamTrackResponseObject, error)
	// GetPublicTracksTile 公开轨迹 (spec §2.8, ADR 0002) as a Mapbox Vector Tile, from z 11
	// (GET /tiles/public-tracks/{z}/{x}/{y})
	GetPublicTracksTile(ctx context.Context, request GetPublicTracksTileRequestObject) (GetPublicTracksTileResponseObject, error)
	// GetTerrainTile A tile of the China PMTiles the offline packages are clipped from (spec §3.1), for 地形 online
	// (GET /tiles/terrain/{layer}/{z}/{x}/{y})
	GetTerrainTile(ctx context.Context, request GetTerrainTileRequestObject) (GetTerrainTileResponseObject, error)
	// GetTiandituTile A 天地图 tile through the server, so the key never ships in the app (spec §2.2)
	// (GET /tiles/tianditu/{layer}/{z}/{x}/{y})
	GetTiandituTile(ctx context.Context, request GetTiandituTileRequestObject) (GetTiandituTileResponseObject, error)
	// GetVersion API version and the oldest client versionCode still served
	// (GET /version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)
	// PostWeather 沿途天气 (spec §2.9) for points along a track at their expected arrival times
	// (POST /weather)
	PostWeather(ctx context.Context, request PostWeatherRequestObject) (PostWeatherResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

